SELECT
PS.MULTI_SCHEME_ID AS MULTI_SCHEME_ID
, SCHEME.NAME AS SCHEME
, PS.SITE_NUMBER AS CONSUMER_ID
, PS.SITE_NAME AS CONSUMER_NAME
, PS.ALTERNATE_NAME AS ALTERNATE_NAME
, PS.LEGAL_NAME AS LEGAL_NAME
, CC.FIRST_NAME AS FIRST_NAME
, CC.LAST_NAME AS LAST_NAME
, CASE WHEN PS.MULTI_SCHEME_ID = 10002 THEN NVL(CC.EMAIL, PS.PO_COMMUNICATION_EMAIL) ELSE CC.EMAIL END AS EMAIL
, AE.ALTERNATE_EMAIL AS ALTERNATE_EMAIL
, R_TT.VALUE AS CONSUMER_TYPE
, CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)) AS REGISTRATION_DATE
, TO_CHAR(CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)),'YYYYMMDD') AS REGISTRATION_DATE_KEY
, PS.STATUS AS STATUS
, PS.GENDER AS GENDER
, R_A.VALUE AS AGE_BRACKET
, PS.GST_REGISTERED AS GST_REGISTERED
, PS.GST_CONCESSION AS GST_CONCESSION
, PS.ADDRESS_LINE_1 AS ADDRESS_LINE_1
, PS.ADDRESS_LINE_2 AS ADDRESS_LINE_2
, INITCAP(TRIM(PS.CITY_SUBURB)) AS SUBURB
, PS.STATE AS STATE
, PS.POST_CODE AS POSTCODE
, CASE WHEN COUNT(DISTINCT SCHEME.NAME) OVER (PARTITION BY PS.SITE_NAME ||  COALESCE(CC.EMAIL,PS.CREATED_BY)) > 1 THEN '2. Signed up to both schemes' WHEN SCHEME.NAME != PS.STATE AND PS.STATE IN ('WA','QLD') THEN '1. Signed up to incorrect scheme' ELSE '' END AS ISSUE_DESCRIPTION
, NVL(SSC.LGA, POA.LGA) AS LGA
, NVL(SSC.REGION, POA.REGION) AS REGION
, NVL(SSC.SUBREGION, POA.SUBREGION) AS SUBREGION
, PS.SITE_ADDR_CONTACT_PHONE_NUMBER AS PHONE_NUMBER
, CC.MOBILE_PHONE_NUMBER AS MOBILE
, PS.TAX_REGISTRATION_NUMBER AS ABN
, PS.AP_TAX_CLASS AS AP_TAX_CLASS
, PS.ERP_BUSINESS_RELATIONSHIP AS ERP_BUSINESS_RELATIONSHIP
, PS.TAX_ORGANIZATION_TYPE AS TAX_ORGANISATION_TYPE
, PS.ESTABLISHED_DATE AS ESTABLISHED_DATE
, PS.INACTIVE_DATE AS INACTIVE_DATE
, PS.CRM_SITE_ID AS CRM_SITE_ID
, PS.ERP_ADDRESS_ID AS ERP_ADDRESS_ID
, PS.PO_COMMUNICATION_EMAIL AS PO_COMMUNICATION_EMAIL
, PS.PYMT_REMIT_ADV_EMAIL AS PYMT_REMIT_ADV_EMAIL
, PS.TERMS_AND_CONDITIONS_ACCEPTED AS TERMS_AND_CONDITIONS_ACCEPTED
, CASE WHEN PS.ATTRIBUTE4 = '1' THEN 'Yes' ELSE 'No' END AS THIRD_PARTY_FLAG
, PS.PARTICIPANT_ID AS SUPPLIER_ID
, PS.PARTICIPANT_NUMBER AS SUPPLIER_NUMBER
, PS.PARTICIPANT_NAME AS SUPPLIER_NAME
, PS.CREATED_ON AS REGISTRATION_DATE_UTC
, C.COLLECTION_QTY_STD AS COLLECTION_QTY_STD
, C.TRANSACTION_COUNT_STD AS TRANSACTION_COUNT_STD
, C.LAST_TRANSACTION_DATE AS LAST_TRANSACTION_DATE
, C.FIRST_TRANSACTION_DATE AS FIRST_TRANSACTION_DATE
, CASE WHEN C.TRANSACTION_COUNT_STD >= 1 THEN 'Transacted' ELSE 'Never Transacted' END AS HAS_TRANSACTED
, CASE WHEN C.TRANSACTION_COUNT_STD = 1 THEN NULL ELSE DATEDIFF('DAY', C.FIRST_TRANSACTION_DATE, C.LAST_TRANSACTION_DATE)/(C.TRANSACTION_COUNT_STD - 1) END AS CYCLE
, ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) AS AVG_DAYS_BETWEEN_TRANSACTIONS
, CASE WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 0 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 20 THEN '0-20' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 21 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 40 THEN '21-40' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 41 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 60 THEN '41-60' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 61 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 80 THEN '61-80' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 81 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 100 THEN '81-100' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 101 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 120 THEN '101-120' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 121 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 140 THEN '121-140'WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 141 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 160 THEN '141-160' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 161 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 180 THEN '161-180' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 181 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 200 THEN '181-200' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 201 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 220 THEN '201-220' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 221 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 240 THEN '221-240' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 241 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 260 THEN '241-260' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 261 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 280 THEN '261-280' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 281 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 300 THEN '281-300' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 301 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 320 THEN '301-320' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 321 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 340 THEN '321-340' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 341 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 360 THEN '341-360' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 361 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 380 THEN '361-380' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 381 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 400 THEN '381-400' WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) > 400 THEN '>400' END AS AVG_DAYS_BETWEEN_TRANSACTIONS_BANDING
, CASE WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 0 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 20 THEN 1 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 21 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 40 THEN 2 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 41 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 60 THEN 3 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 61 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 80 THEN 4 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 81 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 100 THEN 5 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 101 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 120 THEN 6 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 121 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 140 THEN 7 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 141 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 160 THEN 8 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 161 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 180 THEN 9 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 181 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 200 THEN 10 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 201 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 220 THEN 11 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 221 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 240 THEN 12 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 241 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 260 THEN 13 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 261 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 280 THEN 14 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 281 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 300 THEN 15 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 301 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 320 THEN 16 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 321 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 340 THEN 17 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 341 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 360 THEN 18 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 361 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 380 THEN 19 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) >= 381 AND ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) <= 400 THEN 20 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) > 400 THEN 21 WHEN ROUND(DATEDIFF('DAY', PS.CREATED_ON, SYSDATE())/C.TRANSACTION_COUNT_STD, 0) IS NULL THEN 22 END AS AVG_DAYS_BETWEEN_TRANSACTIONS_ORDER
, R_G.VALUE AS CUSTOMER_GROUP
, INITCAP(CASE WHEN PS.PARTICIPANT_GROUP_ID = 1534 THEN NVL(GI.CUSTOMER_TYPE_GROUP, 'Individual Non-team') ELSE R_G.VALUE END) AS CUSTOMER_TYPE_GROUP
, CASE WHEN PS.PARTICIPANT_GROUP_ID = 1534 THEN 'Individual' ELSE 'Group' END AS INDIVIDUAL_GROUP_FLAG
, G.TOTAL_MEMBERS AS TOTAL_MEMBERS
, G.TOTAL_CAPTAINS AS TOTAL_CAPTAINS
, G.TOTAL_TEAMMATES AS TOTAL_TEAMMATES
, CASE WHEN G.TOTAL_MEMBERS BETWEEN 1 AND 3 THEN '1-3 members' WHEN G.TOTAL_MEMBERS BETWEEN 4 AND 6 THEN '4-6 members' WHEN G.TOTAL_MEMBERS BETWEEN 7 AND 10 THEN '7-10 members' WHEN G.TOTAL_MEMBERS BETWEEN 11 AND 143 THEN '11-14 members' WHEN G.TOTAL_MEMBERS >= 15 THEN '15+ members' ELSE NULL END AS TOTAL_MEMBERS_BANDING
, CASE WHEN G.TOTAL_MEMBERS BETWEEN 1 AND 3 THEN '1' WHEN G.TOTAL_MEMBERS BETWEEN 4 AND 6 THEN '2' WHEN G.TOTAL_MEMBERS BETWEEN 7 AND 10 THEN '3' WHEN G.TOTAL_MEMBERS BETWEEN 11 AND 143 THEN '4' WHEN G.TOTAL_MEMBERS >= 15 THEN '5' ELSE NULL END AS TOTAL_MEMBERS_BANDING_ORDER
, GC.GROUP_TRANSACTION_COUNT_STD AS GROUP_TRANSACTION_COUNT_STD
, GC.GROUP_COLLECTION_QTY_STD AS GROUP_COLLECTION_QTY_STD
, PS.DONATION_PARTNER_FLAG AS DONATION_PARTNER_FLAG
, PAY.PAYMENT_METHOD AS DEFAULT_PAYMENT_METHOD
, NVL(NULLIF(PAY.DELEGATED_SITE_NUMBER,''), '-') AS DELEGATED_CONSUMER_ID
, NVL(NULLIF(PAY.DELEGATED_SITE_NAME,''), '-') AS DELEGATED_CONSUMER_NAME
, NVL(NULLIF(PAY.DELEGATED_LEGAL_NAME,''), '-') AS DELEGATED_LEGAL_NAME
, CD.DELEGATED_FIRST_TRANSACTION_DATE AS DELEGATED_FIRST_TRANSACTION_DATE
, CD.DELEGATED_LAST_TRANSACTION_DATE AS DELEGATED_LAST_TRANSACTION_DATE
, DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) AS FIRST_TRANSACTION_AFTER_REGISTRATION_DAYS
, CASE WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) <= 7 THEN '0-7 days' WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) BETWEEN 8 AND 14 THEN '8-14 days' WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) BETWEEN 15 AND 21 THEN '15-21 days' WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) BETWEEN 22 AND 30 THEN '22-30 days' WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) BETWEEN 31 AND 45 THEN '31-45 days' WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) BETWEEN 45 AND 60 THEN '45-60 days' WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) >= 61 THEN '61+ days' END AS FIRST_TRANSACTION_AFTER_REGISTRATION_DAYS_BANDING
, CASE WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) <= 7 THEN 1 WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) BETWEEN 8 AND 14 THEN 2 WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) BETWEEN 15 AND 21 THEN 3 WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) BETWEEN 22 AND 30 THEN 4 WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) BETWEEN 31 AND 45 THEN 5 WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) BETWEEN 45 AND 60 THEN 6 WHEN DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.FIRST_TRANSACTION_DATE) >= 61 THEN 7 END AS FIRST_TRANSACTION_AFTER_REGISTRATION_DAYS_BANDING_ORDER
, DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) AS DAYS_AFTER_LAST_TRANSACTION
, CASE WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) <= 30 THEN '0-30 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 31 AND 60 THEN '31-60 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 61 AND 90 THEN '61-90 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 91 AND 120 THEN '91-120 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 121 AND 150 THEN '121-150 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 151 AND 180 THEN '151-180 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 181 AND 210 THEN '181-210 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 211 AND 240 THEN '211-240 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 241 AND 270 THEN '241-270 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 271 AND 300 THEN '271-300 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 301 AND 330 THEN '301-330 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 331 AND 360 THEN '331-360 days' WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) >= 361 THEN '361+ days' END AS DAYS_AFTER_LAST_TRANSACTION_BANDING
, CASE WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) <= 30 THEN 1 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 31 AND 60 THEN 2 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 61 AND 90 THEN 3 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 91 AND 120 THEN 4 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 121 AND 150 THEN 5 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 151 AND 180 THEN 6 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 181 AND 210 THEN 7 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 211 AND 240 THEN 8 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 241 AND 270 THEN 9 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 271 AND 300 THEN 10 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 301 AND 330 THEN 11 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) BETWEEN 331 AND 360 THEN 12 WHEN DATEDIFF('DAY', C.LAST_TRANSACTION_DATE, SYSDATE()) >= 361 THEN 13 END AS DAYS_AFTER_LAST_TRANSACTION_BANDING_ORDER
, DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.LAST_TRANSACTION_DATE) AS RETENTION_DAY
, V.TOTAL_VISITS_STD AS TOTAL_VISITS_STD
, V.VISITS_IN_12_MONTHS AS VISITS_IN_12_MONTHS
, CASE WHEN V.VISITS_IN_12_MONTHS >=2 THEN 'Y' ELSE 'N' END AS MORE_THAN_2_VISITS_IN_12_MONTHS
, C.COLLECTION_QTY_STD / V.TOTAL_VISITS_STD AS AVG_COLLECTION_QTY_PER_VISIT
, C.COLLECTION_QTY_STD / NULLIF(DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.LAST_TRANSACTION_DATE) , 0) * 365 AS AVG_ANNUAL_COLLECTION_QTY
, V.TOTAL_VISITS_STD / NULLIF(DATEDIFF('DAY', CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(PS.CREATED_ON AS TIMESTAMP)), C.LAST_TRANSACTION_DATE), 0) * 365 AS AVG_ANNUAL_VISITS
, GOAL.LAST_GOAL_ID AS LAST_GOAL_ID
, GOAL.LAST_GOAL_NAME AS LAST_GOAL_NAME
, GOAL.LAST_GOAL_START_DATE AS LAST_GOAL_START_DATE
, GOAL.LAST_GOAL_END_DATE AS LAST_GOAL_END_DATE
, GOAL.LAST_ACTIVE_GOAL_FLAG AS LAST_ACTIVE_GOAL_FLAG
, GOAL.LAST_ACTIVE_GOAL_REACHED_FLAG AS LAST_ACTIVE_GOAL_REACHED_FLAG
, GOAL.TOTAL_GOALS AS TOTAL_GOALS
, GOAL.TOTAL_ELAPSED_GOALS AS TOTAL_ELAPSED_GOALS
, GOAL.TOTAL_REACHED_ELAPSED_GOALS AS TOTAL_REACHED_ELAPSED_GOALS
, GOAL.AVG_DAYS_FOR_GOAL_COMPLETION AS AVG_DAYS_FOR_GOAL_COMPLETION
, GOAL.AVG_GOAL_AMOUNT AS AVG_GOAL_AMOUNT
, GOAL.GOAL_AVG_COLLECTION_QTY AS GOAL_AVG_COLLECTION_QTY
, GOAL.GOAL_AVG_GROSS_AMOUNT AS GOAL_AVG_GROSS_AMOUNT
, GOAL.GOAL_AVG_TRANSACTIONS AS GOAL_AVG_TRANSACTIONS
, GOAL.GOAL_TOTAL_COLLECTION_QTY AS GOAL_TOTAL_COLLECTION_QTY
, GOAL.GOAL_TOTAL_GROSS_AMOUNT AS GOAL_TOTAL_GROSS_AMOUNT
, GOAL.GOAL_TOTAL_TRANSACTIONS AS GOAL_TOTAL_TRANSACTIONS
, CASE WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 0 AND 30 THEN '0 - 30' WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 31 AND 60 THEN '31 - 60' WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 61 AND 90 THEN '61 - 90' WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 91 AND 120 THEN '91 - 120' WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 121 AND 150 THEN '121 - 150' WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 151 AND 180 THEN '151 - 180' WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 181 AND 210 THEN '181 - 210' WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 211 AND 240 THEN '211 - 240' WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 241 AND 270 THEN '241 - 270' WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 271 AND 300 THEN '271 - 300' WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION >= 301 THEN '> 300' END AS AVG_DAYS_FOR_GOAL_COMPLETION_BANDING
, CASE WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 0 AND 30 THEN 1 WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 31 AND 60 THEN 2 WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 61 AND 90 THEN 3 WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 91 AND 120 THEN 4 WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 121 AND 150 THEN 5 WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 151 AND 180 THEN 6 WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 181 AND 210 THEN 7 WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 211 AND 240 THEN 8 WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 241 AND 270 THEN 9 WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION BETWEEN 271 AND 300 THEN 10 WHEN GOAL.AVG_DAYS_FOR_GOAL_COMPLETION >= 301 THEN 11 END AS AVG_DAYS_FOR_GOAL_COMPLETION_BANDING_ORDER
, CASE WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 0 AND 30 THEN '0 - 30' WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 31 AND 60 THEN '31 - 60' WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 61 AND 90 THEN '61 - 90' WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 91 AND 120 THEN '91 - 120' WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 121 AND 150 THEN '121 - 150' WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 151 AND 180 THEN '151 - 180' WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 181 AND 210 THEN '181 - 210' WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 211 AND 240 THEN '211 - 240' WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 241 AND 270 THEN '241 - 270' WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 271 AND 300 THEN '271 - 300' WHEN GOAL.AVG_GOAL_AMOUNT >= 301 THEN '> 300' END AS AVG_GOAL_AMOUNT_BANDING
, CASE WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 0 AND 30 THEN 1 WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 31 AND 60 THEN 2 WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 61 AND 90 THEN 3 WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 91 AND 120 THEN 4 WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 121 AND 150 THEN 5 WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 151 AND 180 THEN 6 WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 181 AND 210 THEN 7 WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 211 AND 240 THEN 8 WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 241 AND 270 THEN 9 WHEN GOAL.AVG_GOAL_AMOUNT BETWEEN 271 AND 300 THEN 10 WHEN GOAL.AVG_GOAL_AMOUNT >= 301 THEN 11 END AS AVG_GOAL_AMOUNT_BANDING_ORDER
, CASE WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 0 AND 30 THEN '0 - 30' WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 31 AND 60 THEN '31 - 60' WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 61 AND 90 THEN '61 - 90' WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 91 AND 120 THEN '91 - 120' WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 121 AND 150 THEN '121 - 150' WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 151 AND 180 THEN '151 - 180' WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 181 AND 210 THEN '181 - 210' WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 211 AND 240 THEN '211 - 240' WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 241 AND 270 THEN '241 - 270' WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 271 AND 300 THEN '271 - 300' WHEN GOAL.GOAL_AVG_COLLECTION_QTY >= 301 THEN '> 300' END AS GOAL_AVG_COLLECTION_QTY_BANDING
, CASE WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 0 AND 30 THEN 1 WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 31 AND 60 THEN 2 WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 61 AND 90 THEN 3 WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 91 AND 120 THEN 4 WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 121 AND 150 THEN 5 WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 151 AND 180 THEN 6 WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 181 AND 210 THEN 7 WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 211 AND 240 THEN 8 WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 241 AND 270 THEN 9 WHEN GOAL.GOAL_AVG_COLLECTION_QTY BETWEEN 271 AND 300 THEN 10 WHEN GOAL.GOAL_AVG_COLLECTION_QTY >= 301 THEN 11 END AS GOAL_AVG_COLLECTION_QTY_BANDING_ORDER
, CASE WHEN GOAL.GOAL_AVG_TRANSACTIONS = 0 THEN '0' WHEN GOAL.GOAL_AVG_TRANSACTIONS = 1 THEN '1' WHEN GOAL.GOAL_AVG_TRANSACTIONS = 2 THEN '2' WHEN GOAL.GOAL_AVG_TRANSACTIONS = 3 THEN '3' WHEN GOAL.GOAL_AVG_TRANSACTIONS = 4 THEN '4' WHEN GOAL.GOAL_AVG_TRANSACTIONS = 5 THEN '5' WHEN GOAL.GOAL_AVG_TRANSACTIONS = 6 THEN '6' WHEN GOAL.GOAL_AVG_TRANSACTIONS = 7 THEN '7' WHEN GOAL.GOAL_AVG_TRANSACTIONS = 8 THEN '8' WHEN GOAL.GOAL_AVG_TRANSACTIONS = 9 THEN '9' WHEN GOAL.GOAL_AVG_TRANSACTIONS = 10 THEN '10' WHEN GOAL.GOAL_AVG_TRANSACTIONS = 11 THEN '11' WHEN GOAL.GOAL_AVG_TRANSACTIONS >= 12 THEN '>= 12' END AS GOAL_AVG_TRANSACTIONS_BANDING
, CASE WHEN GOAL.GOAL_AVG_TRANSACTIONS = 0 THEN 0 WHEN GOAL.GOAL_AVG_TRANSACTIONS = 1 THEN 1 WHEN GOAL.GOAL_AVG_TRANSACTIONS = 2 THEN 2 WHEN GOAL.GOAL_AVG_TRANSACTIONS = 3 THEN 3 WHEN GOAL.GOAL_AVG_TRANSACTIONS = 4 THEN 4 WHEN GOAL.GOAL_AVG_TRANSACTIONS = 5 THEN 5 WHEN GOAL.GOAL_AVG_TRANSACTIONS = 6 THEN 6 WHEN GOAL.GOAL_AVG_TRANSACTIONS = 7 THEN 7 WHEN GOAL.GOAL_AVG_TRANSACTIONS = 8 THEN 8 WHEN GOAL.GOAL_AVG_TRANSACTIONS = 9 THEN 9 WHEN GOAL.GOAL_AVG_TRANSACTIONS = 10 THEN 10 WHEN GOAL.GOAL_AVG_TRANSACTIONS = 11 THEN 11 WHEN GOAL.GOAL_AVG_TRANSACTIONS >= 12 THEN 12 END AS GOAL_AVG_TRANSACTIONS_BANDING_ORDER
, ABN.ABN AS ABR_ABN
, ABN.ABNSTATUSFROMDATE AS ABR_ABN_STATUS_FROM_DATE
, ABN.ABNSTATUS AS ABR_ABN_STATUS
, ABN.GSTSTATUS AS ABR_GST_STATUS
, CASE WHEN ABN.ENTITYTYPETEXT = 'Individual/Sole Trader' THEN ABN.FAMILYNAME || ' ' || ABN.GIVENNAME ELSE ABN.NONINDIVIDUALNAMETEXT END AS ABR_LEGAL_NAME
, CASE WHEN ABN.ENTITYTYPETEXT = 'Individual/Sole Trader' THEN ABN.GIVENNAME || '%' || ABN.FAMILYNAME ELSE ABN.NONINDIVIDUALNAMETEXT END AS ABR_LEGAL_NAME_SOLE_TRADER_FOR_RECONCILIATION
, ABN.ENTITYTYPETEXT AS ABR_ENTITY_TYPE
, CASE WHEN ABN.ABN IS NULL THEN 'ABN Not Registered' ELSE 'Reconciled' END AS ABN_RECONCILIATION
, CASE WHEN (PS.STATUS = 'Active' AND ABN.ABNSTATUS = 'ACT') OR (PS.STATUS = 'Inactive' AND ABN.ABNSTATUS = 'CAN') THEN 'Reconciled' WHEN PS.STATUS = 'Inactive' AND ABN.ABNSTATUS = 'ACT' THEN 'Account Inactive, ABR Active' WHEN PS.STATUS = 'Active' AND ABN.ABNSTATUS = 'CAN' THEN 'Account Active, ABR Inactive' ELSE 'Not Reconciled' END AS ABN_STATUS_RECONCILIATION
, CASE WHEN ABN.ENTITYTYPETEXT = 'Individual/Sole Trader' AND REPLACE(TRIM(UPPER(CASE WHEN PS.LEGAL_NAME LIKE 'INVALID %' THEN REPLACE(PS.LEGAL_NAME, 'INVALID ') ELSE PS.LEGAL_NAME END)), ',') LIKE ANY (UPPER(ABR_LEGAL_NAME) || '%', UPPER(ABR_LEGAL_NAME_SOLE_TRADER_FOR_RECONCILIATION) || '%') THEN 'Reconciled' WHEN REPLACE(REPLACE(REPLACE(TRIM(LOWER(CASE WHEN PS.LEGAL_NAME LIKE 'INVALID %' THEN REPLACE(PS.LEGAL_NAME, 'INVALID ') ELSE PS.LEGAL_NAME END)), 'pty.', 'pty'), 'ltd.', 'ltd'), 'co.', 'co') = REPLACE(REPLACE(REPLACE(TRIM(LOWER(ABN.NONINDIVIDUALNAMETEXT)), 'pty.', 'pty'), 'ltd.', 'ltd'), 'co.', 'co') THEN 'Reconciled' ELSE 'Not Reconciled' END AS LEGAL_NAME_RECONCILIATION
, CASE WHEN ABN_RECONCILIATION = 'Reconciled' AND ABN_STATUS_RECONCILIATION IN ('Reconciled', 'Account Inactive, ABR Active') AND LEGAL_NAME_RECONCILIATION = 'Reconciled' THEN 'Reconciled' ELSE 'Not Reconciled' END AS FINAL_RECONCILIATION
, PS.CREATED_BY AS CREATED_BY
, PS.CREATED_ON_PS AS CREATED_ON_UTC
, PS.LAST_MODIFIED_BY AS LAST_MODIFIED_BY
, GREATEST(NVL(PS.LAST_MODIFIED_ON, TO_DATE('01/01/1900', 'DD/MM/YYYY')), NVL(PS.LAST_MODIFIED_ON, TO_DATE('01/01/1900', 'DD/MM/YYYY')), NVL(CC.LAST_MODIFIED_ON_UTC, TO_DATE('01/01/1900', 'DD/MM/YYYY')), NVL(C.FIRST_TRANSACTION_DATE, TO_DATE('01/01/1900', 'DD/MM/YYYY')), NVL(PAY.LAST_MODIFIED_ON_UTC, TO_DATE('01/01/1900', 'DD/MM/YYYY'))) AS LAST_MODIFIED_ON_UTC
, SYSDATE() AS INSERT_DATE_UTC
FROM
    ( SELECT
    PS.MULTI_SCHEME_ID
    , PS.SITE_NUMBER
    , PS.SITE_NAME
    , NVL(DECODE(DP.ACTIVE, 'Y', 'Active', 'N', 'Inactive'), PS.STATUS) AS STATUS
    , P.ALTERNATE_NAME
    , P.LEGAL_NAME
    , P.GENDER
    , P.GST_REGISTERED
    , P.GST_CONCESSION
    , P.TAX_REGISTRATION_NUMBER
    , P.AP_TAX_CLASS
    , P.ERP_BUSINESS_RELATIONSHIP
    , P.TAX_ORGANIZATION_TYPE
    , P.ESTABLISHED_DATE
    , P.INACTIVE_DATE
    , P.PARTICIPANT_ID
    , P.PARTICIPANT_NUMBER
    , P.PARTICIPANT_NAME
    , P.PARTICIPANT_GROUP_ID
    , P.AGE_BRACKET_ID
    , P.CREATED_ON
    , PS.ADDRESS_LINE_1
    , PS.ADDRESS_LINE_2
    , NVL(NULLIF(PS.CITY_SUBURB, ''), '-') AS CITY_SUBURB
    , PS.STATE
    , PS.POST_CODE
    , PS.SITE_ADDR_CONTACT_PHONE_NUMBER
    , PS.CRM_SITE_ID
    , PS.ERP_ADDRESS_ID
    , PS.PO_COMMUNICATION_EMAIL
    , PS.PYMT_REMIT_ADV_EMAIL
    , PS.TERMS_AND_CONDITIONS_ACCEPTED
    , PS.ATTRIBUTE4
    , PS.PARTICIPANT_SITE_ID
    , PS.TAXONOMY_TYPE_ID
    , PS.SITE_TYPE_ID
    , CASE WHEN DP.SCHEME_PARTICIPANT_ID IS NOT NULL THEN 1 ELSE 0 END AS DONATION_PARTNER_FLAG
    , PS.CREATED_BY
    , NVL(DP.CREATED_AT, PS.CREATED_ON) AS CREATED_ON_PS
    , PS.LAST_MODIFIED_BY
    , PS.LAST_MODIFIED_ON
    FROM
    {{ source('CES_MSCM', 'MDT_PARTICIPANT_SITES') }} AS PS
    INNER JOIN {{ source('CES_MSCM', 'MDT_PARTICIPANTS') }} AS P
    ON P.PARTICIPANT_ID = PS.PARTICIPANT_ID
    LEFT JOIN {{ source('CES_MSCM_KAFKA', 'DONATION_PARTNERS') }} AS DP
    ON PS.SITE_NUMBER = DP.SCHEME_PARTICIPANT_ID
    WHERE PS.SITE_TYPE_ID = '1537'
 
    UNION ALL
 
    SELECT
    DP.MULTI_SCHEME_ID AS MULTI_SCHEME_ID
    , DP.SCHEME_PARTICIPANT_ID AS SITE_NUMBER
    , DP.TRADING_NAME AS SITE_NAME
    , DECODE(DP.ACTIVE, 'Y', 'Active', 'N', 'Inactive') AS STATUS
    , '' AS ALTERNATE_NAME
    , DP.LEGAL_NAME AS LEGAL_NAME
    , '' AS GENDER
    , CASE WHEN DP.GST_REGISTERED IS NOT NULL THEN 1 ELSE 0 END AS GST_REGISTERED
    , NULL AS GST_CONCESSION
    , DP.ABN || '' AS TAX_REGISTRATION_NUMBER
    , '' AS AP_TAX_CLASS
    , '' AS ERP_BUSINESS_RELATIONSHIP
    , DP.ENTITY_TYPE AS TAX_ORGANIZATION_TYPE
    , DP.GST_REGISTERED AS ESTABLISHED_DATE
    , NULL AS INACTIVE_DATE
    , NULL AS PARTICIPANT_ID --FOR ONES IN OUR DATA
    , NULL AS PARTICIPANT_NUMBER --FOR ONES IN OUR DATA
    , '' AS PARTICIPANT_NAME --FOR ONES IN OUR DATA
    , NULL AS PARTICIPANT_GROUP_ID --FOR ONES IN OUR DATA
    , NULL AS AGE_BRACKET_ID --FOR ONES IN OUR DATA
    , DP.CREATED_AT AS CREATED_ON --FOR ONES IN OUR DATA
    , '' AS ADDRESS_LINE_1
    , '' AS ADDRESS_LINE_2
    , '-' AS CITY_SUBURB
    , '' AS STATE
    , '' AS POST_CODE
    , '' AS SITE_ADDR_CONTACT_PHONE_NUMBER
    , NULL AS CRM_SITE_ID
    , NULL AS ERP_ADDRESS_ID
    , DP.EMAIL_ADDRESS AS PO_COMMUNICATION_EMAIL
    , '' AS PYMT_REMIT_ADV_EMAIL
    , NULL AS TERMS_AND_CONDITIONS_ACCEPTED
    , NULL AS ATTRIBUTE4
    , NULL AS PARTICIPANT_SITE_ID
    , NULL AS TAXONOMY_TYPE_ID
    , NULL AS SITE_TYPE_ID
    , 1 AS DONATION_PARTNER_FLAG
    , '' AS CREATED_BY
    , DP.CREATED_AT AS CREATED_ON_PS
    , '' AS LAST_MODIFIED_BY
    , DP.UPDATED_AT AS LAST_MODIFIED_ON
    FROM
    {{ source('CES_MSCM_KAFKA', 'DONATION_PARTNERS') }} AS DP
    LEFT JOIN {{ source('CES_MSCM', 'MDT_PARTICIPANT_SITES') }} AS PS
    ON DP.SCHEME_PARTICIPANT_ID = PS.SITE_NUMBER
    WHERE PS.SITE_NUMBER IS NULL
) PS
INNER JOIN {{ source('CES_MSCM', 'SCHEME') }} AS SCHEME
ON PS.MULTI_SCHEME_ID = SCHEME.MULTI_SCHEME_ID
LEFT JOIN {{ source('CES_MSCM', 'SCHEME_REF_CODES') }} AS R_A
ON PS.AGE_BRACKET_ID = R_A.SCHEME_REF_CODES_ID
LEFT JOIN (
    SELECT CR.PARTICIPANT_SITE_ID
        ,C.FIRST_NAME
        ,C.LAST_NAME
        ,C.EMAIL
        ,C.MOBILE_PHONE_NUMBER
        ,GREATEST(NVL(C.LAST_MODIFIED_ON, TO_DATE('01/01/1900', 'DD/MM/YYYY')), NVL(CR.LAST_MODIFIED_ON, TO_DATE('01/01/1900', 'DD/MM/YYYY'))) AS LAST_MODIFIED_ON_UTC
    FROM {{ source('CES_MSCM', 'MDT_CONTACTS') }} AS C
    LEFT JOIN {{ source('CES_MSCM', 'MDT_CONTACT_ROLES') }} AS CR
        ON C.CONTACT_ID = CR.CONTACT_ID
    LEFT JOIN {{ source('CES_MSCM', 'SCHEME_REF_CODES') }} AS R
        ON CR.ROLE_TYPE_ID = R.SCHEME_REF_CODES_ID
    WHERE CR.ASSIGNMENT_TYPE = 'SITE'
        AND R.CODE = 'AUTHORISED_CONTACT_B2C'
        AND C.PRIMARY = 1
        AND C.ACTIVE = 1
        AND CR.ACTIVE = 1
        AND C.FIRST_NAME IS NOT NULL
        QUALIFY ROW_NUMBER() OVER (PARTITION BY CR.PARTICIPANT_SITE_ID ORDER BY NVL(CR.EFFECTIVE_END_DATE, TO_DATE('01/01/9999', 'DD/MM/YYYY')) DESC) = 1
) CC 
ON PS.PARTICIPANT_SITE_ID = CC.PARTICIPANT_SITE_ID
LEFT JOIN {{ source('CES_MSCM', 'SCHEME_REF_CODES') }} AS R_TT
ON PS.TAXONOMY_TYPE_ID = R_TT.SCHEME_REF_CODES_ID
LEFT JOIN {{ source('CES_MSCM', 'SCHEME_REF_CODES') }} AS R_G
ON PS.PARTICIPANT_GROUP_ID = R_G.SCHEME_REF_CODES_ID
LEFT JOIN {{ ref('REF_STATE') }} AS STATE
ON STATE.STATE = PS.STATE 
LEFT JOIN {{ ref('REF_LOCALITY_SSC') }} AS SSC
ON PS.CITY_SUBURB = SSC.SUBURB
AND PS.POST_CODE = SSC.POSTCODE
AND STATE.STATE_NAME = SSC.STATE
LEFT JOIN {{ ref('REF_LOCALITY_POA') }} AS POA
ON PS.POST_CODE = POA.POSTCODE
AND STATE.STATE_NAME = POA.STATE
LEFT JOIN {{ source('CES_ABN', 'ABN_EXTRACT') }} AS ABN
ON PS.TAX_REGISTRATION_NUMBER = ABN.ABN || ''
LEFT JOIN (
    SELECT
    CG.CONSUMER_ID_GROUP,
    COUNT(CG.CONSUMER_ID_INDIVIDUAL) AS TOTAL_MEMBERS,
    SUM(CASE WHEN CG.GROUP_ROLE = 'CAPTAIN' THEN 1 ELSE 0 END) AS TOTAL_CAPTAINS,
    SUM(CASE WHEN CG.GROUP_ROLE = 'TEAMMATE' THEN 1 ELSE 0 END) AS TOTAL_TEAMMATES
    FROM {{ ref('CONSUMER_GROUP') }} AS CG
    WHERE TO_CHAR(SYSDATE(), 'YYYYMMDD') BETWEEN TO_CHAR(CG.EFFECTIVE_START_DATE_GROUP, 'YYYYMMDD') AND NVL(TO_CHAR(DATEADD(DAY, -1, CG.EFFECTIVE_END_DATE_GROUP), 'YYYYMMDD'), '99990101')
    AND CG.CONSUMER_ID_INDIVIDUAL IS NOT NULL
    GROUP BY
    CG.CONSUMER_ID_GROUP
) G
ON PS.SITE_NUMBER = G.CONSUMER_ID_GROUP
LEFT JOIN (
    SELECT
    CG.CONSUMER_ID_INDIVIDUAL,
    CG.CUSTOMER_GROUP || ' ' || CG.GROUP_ROLE AS CUSTOMER_TYPE_GROUP
    FROM {{ ref('CONSUMER_GROUP') }} AS CG
    WHERE TO_CHAR(SYSDATE(), 'YYYYMMDD') BETWEEN TO_CHAR(CG.EFFECTIVE_START_DATE_GROUP, 'YYYYMMDD') AND NVL(TO_CHAR(DATEADD(DAY, -1, CG.EFFECTIVE_END_DATE_GROUP), 'YYYYMMDD'), '99990101')
    AND CG.CONSUMER_ID_INDIVIDUAL IS NOT NULL
    QUALIFY ROW_NUMBER() OVER (PARTITION BY CONSUMER_ID_INDIVIDUAL ORDER BY EFFECTIVE_START_DATE_GROUP DESC) = 1
) GI
ON PS.SITE_NUMBER = GI.CONSUMER_ID_INDIVIDUAL
LEFT JOIN (
    SELECT
    HDR.CONSUMER_ID_GROUP,
    COUNT(HDR.TRANSACTION_ID) AS GROUP_TRANSACTION_COUNT_STD,
    SUM(HDR.COLLECTION_QTY) AS GROUP_COLLECTION_QTY_STD
    FROM {{ ref('CRP_COLLECTION_HDR') }} AS HDR
    WHERE GROUP_TRANSACTION_FLAG = 1
    GROUP BY
    HDR.CONSUMER_ID_GROUP
) GC
ON PS.SITE_NUMBER = GC.CONSUMER_ID_GROUP
LEFT JOIN (
    SELECT 
    H.CONSUMER_ID
    , SUM(H.COLLECTION_QTY) AS COLLECTION_QTY_STD
    , COUNT(H.ID) AS TRANSACTION_COUNT_STD
    , MAX(TRANSACTION_DATE) AS LAST_TRANSACTION_DATE
    , MIN(TRANSACTION_DATE) AS FIRST_TRANSACTION_DATE
    FROM {{ ref('CRP_COLLECTION_HDR') }} AS H
    GROUP BY
    H.CONSUMER_ID
) C
ON PS.SITE_NUMBER = C.CONSUMER_ID
LEFT JOIN (
    SELECT
    PPP.SCHEME_PARTICIPANT_ID
    , PS.SITE_NUMBER AS DELEGATED_SITE_NUMBER
    , PS.SITE_NAME AS DELEGATED_SITE_NAME
    , P.LEGAL_NAME AS DELEGATED_LEGAL_NAME
    , PPP.PAYMENT_METHOD
    , PPP.LAST_MODIFIED_ON AS LAST_MODIFIED_ON_UTC
    , ROW_NUMBER() OVER (PARTITION BY PPP.SCHEME_PARTICIPANT_ID ORDER BY PPP.LAST_MODIFIED_ON DESC) AS RN
    FROM {{ source('CES_MSCM', 'PYMT_PAY_PARTY_PROFILES') }} AS PPP
    LEFT JOIN {{ source('CES_MSCM', 'MDT_PARTICIPANT_SITES') }} AS PS
    ON PPP.DELEGATED_SITE_ID = PS.PARTICIPANT_SITE_ID
    LEFT JOIN {{ source('CES_MSCM', 'MDT_PARTICIPANTS') }} AS P
    ON PS.PARTICIPANT_ID = P.PARTICIPANT_ID
    WHERE PPP.DEFAULT_FLAG = 'Y'
    AND SYSDATE() BETWEEN NVL(PPP.START_DATE_ACTIVE, TO_DATE('01/JAN/1900', 'DD/MON/YYYY')) AND NVL(PPP.END_DATE_ACTIVE, TO_DATE('01/JAN/9999', 'DD/MON/YYYY'))
) PAY
ON PS.SITE_NUMBER = PAY.SCHEME_PARTICIPANT_ID
LEFT JOIN (
    SELECT
    CONSUMER_ID
    , MIN(TRANSACTION_DATE) AS DELEGATED_FIRST_TRANSACTION_DATE
    , MAX(TRANSACTION_DATE) AS DELEGATED_LAST_TRANSACTION_DATE
    FROM {{ ref('CRP_COLLECTION_HDR') }} AS CCH
    WHERE CCH.CONSUMER_ID <> CCH.RECIPIENT_CONSUMER_ID
    GROUP BY
    CONSUMER_ID
) CD
ON PS.SITE_NUMBER = CD.CONSUMER_ID
LEFT JOIN (
    SELECT
    CCS.CONSUMER_ID
    , AVG(CCS.RETURN_CYCLE) AS AVG_RETURN_CYCLE
    , SUM(CASE WHEN CCS.TRANSACTION_DATE > DATEADD('MONTH', -12, SYSDATE()) THEN 1 ELSE 0 END) AS VISITS_IN_12_MONTHS
    , MAX(CCS.VISIT_SEQUENCE) AS TOTAL_VISITS_STD
    FROM {{ ref('CONSUMER_COLLECTION_SUMMARY_V') }} AS CCS
    GROUP BY
    CCS.CONSUMER_ID
) V
ON PS.SITE_NUMBER = V.CONSUMER_ID
LEFT JOIN (
    SELECT
    GL.CONSUMER_ID
    , GL.GOAL_ID AS LAST_GOAL_ID
    , GL.GOAL_NAME AS LAST_GOAL_NAME
    , GL.GOAL_START_DATE AS LAST_GOAL_START_DATE
    , GL.GOAL_END_DATE AS LAST_GOAL_END_DATE
    , GL.ACTIVE_GOAL_FLAG AS LAST_ACTIVE_GOAL_FLAG
    , CASE WHEN GL.ACTIVE_GOAL_FLAG = 1 AND GL.GOAL_REACHED_FLAG = 1 THEN 1 ELSE 0 END AS LAST_ACTIVE_GOAL_REACHED_FLAG
    , COUNT(GL.GOAL_ID) OVER (PARTITION BY GL.CONSUMER_ID) AS TOTAL_GOALS
    , COUNT(CASE WHEN GL.ACTIVE_GOAL_FLAG = 0 THEN GL.GOAL_ID ELSE NULL END) OVER (PARTITION BY GL.CONSUMER_ID) AS TOTAL_ELAPSED_GOALS
    , COUNT(CASE WHEN GL.ACTIVE_GOAL_FLAG = 0 AND GL.GOAL_REACHED_FLAG = 1 THEN GL.GOAL_ID ELSE NULL END) OVER (PARTITION BY GL.CONSUMER_ID) AS TOTAL_REACHED_ELAPSED_GOALS
    , AVG(GL.DAYS_FOR_GOAL_COMPLETION) OVER (PARTITION BY GL.CONSUMER_ID) AS AVG_DAYS_FOR_GOAL_COMPLETION
    , AVG(GL.GOAL_AMOUNT) OVER (PARTITION BY GL.CONSUMER_ID) AS AVG_GOAL_AMOUNT
    , AVG(CASE WHEN GL.ACTIVE_GOAL_FLAG = 0 THEN GL.AVG_COLLECTION_QTY ELSE NULL END) OVER (PARTITION BY GL.CONSUMER_ID) AS GOAL_AVG_COLLECTION_QTY
    , AVG(CASE WHEN GL.ACTIVE_GOAL_FLAG = 0 THEN GL.AVG_GROSS_AMOUNT ELSE NULL END) OVER (PARTITION BY GL.CONSUMER_ID) AS GOAL_AVG_GROSS_AMOUNT
    , AVG(CASE WHEN GL.ACTIVE_GOAL_FLAG = 0 THEN GL.TOTAL_TRANSACTIONS ELSE NULL END) OVER (PARTITION BY GL.CONSUMER_ID) AS GOAL_AVG_TRANSACTIONS
    , SUM(CASE WHEN GL.ACTIVE_GOAL_FLAG = 0 THEN GL.TOTAL_COLLECTION_QTY ELSE NULL END) OVER (PARTITION BY GL.CONSUMER_ID) AS GOAL_TOTAL_COLLECTION_QTY
    , SUM(CASE WHEN GL.ACTIVE_GOAL_FLAG = 0 THEN GL.TOTAL_GROSS_AMOUNT ELSE NULL END) OVER (PARTITION BY GL.CONSUMER_ID) AS GOAL_TOTAL_GROSS_AMOUNT
    , SUM(CASE WHEN GL.ACTIVE_GOAL_FLAG = 0 THEN GL.TOTAL_TRANSACTIONS ELSE NULL END) OVER (PARTITION BY GL.CONSUMER_ID) AS GOAL_TOTAL_TRANSACTIONS
    FROM {{ ref('CONSUMER_GOAL') }} AS GL
    WHERE GL.GOAL_LAST_MODIFIED_FLAG = 1
    QUALIFY ROW_NUMBER() OVER (PARTITION BY GL.CONSUMER_ID ORDER BY GL.ID DESC) = 1
) GOAL
ON PS.SITE_NUMBER = GOAL.CONSUMER_ID
LEFT JOIN (
    SELECT 
    CR.PARTICIPANT_SITE_ID
    ,NULLIF(TO_CHAR(UD.VALUE, 'UTF8'), '') AS ALTERNATE_EMAIL
    FROM {{ source('CES_DRUPAL', 'CONTACTS') }} AS C
    INNER JOIN {{ source('CES_DRUPAL', 'CONTACT_ROLES') }} AS CR
    ON C.CONTACT_ID = CR.CONTACT_ID
    INNER JOIN {{ source('CES_DRUPAL', 'USERS_FIELD_DATA') }} AS UFD
    ON C.EMAIL = UFD.NAME
    INNER JOIN {{ source('CES_DRUPAL', 'USERS_DATA') }} AS UD
    ON UFD.UID = UD.UID
    WHERE UD.NAME = 'organisation_marketing_email'
    and UD.MODULE = 'cfc_member_core'
    AND CR.ASSIGNMENT_TYPE = 'SITE'
    AND C.PRIMARY = 1
    AND C.ACTIVE = 1
    AND CR.ACTIVE = 1
    AND C.FIRST_NAME IS NOT NULL
    QUALIFY ROW_NUMBER() OVER (PARTITION BY CR.PARTICIPANT_SITE_ID ORDER BY NVL(CR.EFFECTIVE_END_DATE, TO_DATE('01/01/9999', 'DD/MM/YYYY')) DESC) = 1
) AE
ON PS.PARTICIPANT_SITE_ID = AE.PARTICIPANT_SITE_ID
LEFT JOIN (
  SELECT 
  DISTINCT CONSUMER_NUMBER
  FROM {{ source('CES_MSCM', 'MDT_CUSTOMER_UUID') }} AS CU
  WHERE CU.USER_TYPE = 'organisation') CU
ON CU.CONSUMER_NUMBER = PS.SITE_NUMBER
WHERE --PS.SITE_TYPE_ID = '1537'
NVL(PAY.RN, 1) = 1
AND NVL(LOWER(CC.EMAIL), '-') NOT LIKE '%@yopmail%'

UNION ALL
 
